package com.smartproperty.platform.access.controller;
import com.smartproperty.platform.access.*;import com.smartproperty.platform.access.mapper.AccessControlMapper;import com.smartproperty.platform.access.vo.ScopedCommunityVO;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/access") public class AccessScopeController {private final AuthorizationService auth;private final DataScopeService scope;private final AccessControlMapper mapper;public AccessScopeController(AuthorizationService a,DataScopeService s,AccessControlMapper m){auth=a;scope=s;mapper=m;}@GetMapping("/community-scope") public List<ScopedCommunityVO> currentScope(){auth.requirePermission(PermissionCodes.PROPERTY_VIEW);var x=scope.currentCommunityScope();return mapper.selectScopedCommunities(x.global(),x.communityIds());}}
